typedef struct { GHashTable *props; } Order;      /* owner */

void order_set(Order *o, const char *name, GVariant *v) {
    g_hash_table_insert(o->props, g_strdup(name), v);
}
GVariant *order_get(const Order *o, const char *name) {
    return g_hash_table_lookup(o->props, name);  /* NULL may mean absent */
}
